#[derive(Clone, Debug)]
pub struct UserInteractionClient {
    answer: NativeRequestHandle<UserInteractionAnswer>,
    ask: NativeRequestHandle<UserInteractionAsk>,
    pending: NativeRequestHandle<UserInteractionPending>,
}
impl UserInteractionClient {
    pub fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_dependencies(dependencies)
    }

    pub fn from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_requirement(dependencies, requirement_id)
    }

    pub async fn answer(&self, request: AnswerRequest) -> Result<AnswerResponse, UserInteractionAnswerInvocationError> {
        self.answer.invoke(ANSWER_OPERATION, request).await
            .map_err(UserInteractionAnswerInvocationError::Runtime)?
            .map_err(UserInteractionAnswerInvocationError::Domain)
    }

    pub async fn answer_with_context(&self, context: InvocationContext, request: AnswerRequest) -> Result<AnswerResponse, UserInteractionAnswerInvocationError> {
        self.answer.invoke_with_context(ANSWER_OPERATION, context, request).await
            .map_err(UserInteractionAnswerInvocationError::Runtime)?
            .map_err(UserInteractionAnswerInvocationError::Domain)
    }

    pub async fn ask(&self, request: AskRequest) -> Result<AskResponse, UserInteractionAskInvocationError> {
        self.ask.invoke(ASK_OPERATION, request).await
            .map_err(UserInteractionAskInvocationError::Runtime)?
            .map_err(UserInteractionAskInvocationError::Domain)
    }

    pub async fn ask_with_context(&self, context: InvocationContext, request: AskRequest) -> Result<AskResponse, UserInteractionAskInvocationError> {
        self.ask.invoke_with_context(ASK_OPERATION, context, request).await
            .map_err(UserInteractionAskInvocationError::Runtime)?
            .map_err(UserInteractionAskInvocationError::Domain)
    }

    pub async fn pending(&self, request: PendingRequest) -> Result<PendingResponse, UserInteractionPendingInvocationError> {
        self.pending.invoke(PENDING_OPERATION, request).await
            .map_err(UserInteractionPendingInvocationError::Runtime)?
            .map_err(UserInteractionPendingInvocationError::Domain)
    }

    pub async fn pending_with_context(&self, context: InvocationContext, request: PendingRequest) -> Result<PendingResponse, UserInteractionPendingInvocationError> {
        self.pending.invoke_with_context(PENDING_OPERATION, context, request).await
            .map_err(UserInteractionPendingInvocationError::Runtime)?
            .map_err(UserInteractionPendingInvocationError::Domain)
    }
}

impl CapabilityClient for UserInteractionClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            answer: dependencies.one::<UserInteractionAnswer>()?,
            ask: dependencies.one::<UserInteractionAsk>()?,
            pending: dependencies.one::<UserInteractionPending>()?,
        })
    }

    fn from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Self, RuntimeFailure> {
        let dependencies = dependencies.requirement(requirement_id)?;
        Self::from_dependencies(&dependencies)
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for UserInteractionClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    answer: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<UserInteractionAnswer>()?,
                    ask: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<UserInteractionAsk>()?,
                    pending: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<UserInteractionPending>()?,
                    },
                ))
            })
            .collect()
    }

    fn many_from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        let dependencies = dependencies.requirement(requirement_id)?;
        Self::many_from_dependencies(&dependencies)
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum UserInteractionAnswerInvocationError {
    Domain(AnswerError),
    Runtime(RuntimeFailure),
}
#[derive(Clone, Debug, PartialEq)]
pub enum UserInteractionAskInvocationError {
    Domain(AskError),
    Runtime(RuntimeFailure),
}
#[derive(Clone, Debug, PartialEq)]
pub enum UserInteractionPendingInvocationError {
    Domain(PendingError),
    Runtime(RuntimeFailure),
}

#[derive(Clone, Copy, Debug)]
pub struct UserInteractionGuestClient<'a, H: lenso_guest_sdk::HostImports> {
    capability: lenso_guest_sdk::GuestCapability<'a, H>,
}

impl<'a, H: lenso_guest_sdk::HostImports> UserInteractionGuestClient<'a, H> {
    pub fn from_context(context: &'a lenso_guest_sdk::GuestContext<H>) -> Result<Self, lenso_guest_sdk::GuestError<serde_json::Value>> {
        context
            .require(CAPABILITY_ID, DESCRIPTOR_VERSION, &[ANSWER_OPERATION, ASK_OPERATION, PENDING_OPERATION], &[])
            .map(|capability| Self { capability })
    }

    pub fn answer(&self, request: &AnswerRequest) -> Result<AnswerResponse, lenso_guest_sdk::GuestError<AnswerError>> {
        self.capability.request(ANSWER_OPERATION, request)
    }

    pub fn ask(&self, request: &AskRequest) -> Result<AskResponse, lenso_guest_sdk::GuestError<AskError>> {
        self.capability.request(ASK_OPERATION, request)
    }

    pub fn pending(&self, request: &PendingRequest) -> Result<PendingResponse, lenso_guest_sdk::GuestError<PendingError>> {
        self.capability.request(PENDING_OPERATION, request)
    }
}

#[derive(Debug, Default)]
pub struct UserInteractionJsonCodec;

impl lenso_runtime_codec::JsonCapabilityCodec for UserInteractionJsonCodec {
    fn capability_id(&self) -> &'static str { CAPABILITY_ID }

    fn descriptor_version(&self) -> &'static str { DESCRIPTOR_VERSION }

    fn descriptor_digest(&self) -> &'static str { DESCRIPTOR_DIGEST }

    fn request_operations(&self) -> &'static [&'static str] { &[ANSWER_OPERATION, ASK_OPERATION, PENDING_OPERATION] }
    fn stream_operations(&self) -> &'static [&'static str] { &[] }

    fn encode_request(&self, operation: &str, request: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        match operation {
            ANSWER_OPERATION => {
                let value = request.downcast_ref::<AnswerRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            ASK_OPERATION => {
                let value = request.downcast_ref::<AskRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            PENDING_OPERATION => {
                let value = request.downcast_ref::<PendingRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_response(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            ANSWER_OPERATION => serde_json::from_value::<AnswerResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            ASK_OPERATION => serde_json::from_value::<AskResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            PENDING_OPERATION => serde_json::from_value::<PendingResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_domain_error(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            ANSWER_OPERATION => serde_json::from_value::<AnswerError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            ASK_OPERATION => serde_json::from_value::<AskError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            PENDING_OPERATION => serde_json::from_value::<PendingError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn encode_stream_open(&self, operation: &str, _request: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn encode_stream_message(&self, operation: &str, _message: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn decode_stream_message(&self, operation: &str, _value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn decode_stream_domain_error(&self, operation: &str, _value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn invoke_host_request(&self, dependency: lenso_kernel::PluginDependencyHandle, operation: String, request: serde_json::Value, context: InvocationContext) -> lenso_runtime_codec::JsonHostRequestFuture {
        match operation.as_str() {
            ANSWER_OPERATION => {
                let request = serde_json::from_value::<AnswerRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<UserInteractionAnswer>()?;
                    match handle.invoke_with_context(ANSWER_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            ASK_OPERATION => {
                let request = serde_json::from_value::<AskRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<UserInteractionAsk>()?;
                    match handle.invoke_with_context(ASK_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            PENDING_OPERATION => {
                let request = serde_json::from_value::<PendingRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<UserInteractionPending>()?;
                    match handle.invoke_with_context(PENDING_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            _ => Box::pin(std::future::ready(Err(runtime_codec_unknown_operation(&operation)))),
        }
    }

    fn open_host_stream(&self, _dependency: lenso_kernel::PluginStreamDependencyHandle, operation: String, _request: serde_json::Value, _context: InvocationContext) -> lenso_runtime_codec::JsonHostStreamOpenFuture {
        Box::pin(std::future::ready(Err(runtime_codec_unknown_operation(&operation))))
    }
}

fn runtime_codec_protocol_failure() -> RuntimeFailure { RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID } }

fn runtime_codec_unknown_operation(operation: &str) -> RuntimeFailure {
    RuntimeFailure::UnknownOperation { capability: CAPABILITY_ID, operation: operation.to_owned() }
}
